PREFIX brick: <https://brickschema.org/schema/1.3/brick#>
SELECT ?s WHERE {
  ?s a brick:Zone ; rdfs:label "Perimeter_top_ZN_4" .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?s ?label WHERE {
  ?s rdfs:label ?label .
  FILTER (CONTAINS(?label, "ZN_4"))
}

PREFIX ref: <http://www.w3.org/2001/vocab/...>
SELECT ?point ?tsid ?label WHERE {
  ?point ref:isPartOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z05> ;
         ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?point rdfs:label ?label }
}

PREFIX brick: <https://brickschema.org/schema/1.2/brick#>
SELECT ?point ?label WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z05> brick:hasPoint ?point .
  OPTIONAL { ?point rdfs:label ?label }
}

